fn nullCountForArray(data: *const ArrayData) ConcatArrayError!usize {
    if (data.null_count) |count| return count;
    if (data.validity()) |v| {
        const end = data.offset + data.length;
        if (bitmap.byteLength(end) > v.data.len) return error.InvalidInput;
        return bitmap.countUnsetBitsInRange(v.data, data.offset, end);
    }
    return 0;
}

fn concatValidityBuffer(
    allocator: std.mem.Allocator,
    left: *const ArrayData,
    right: *const ArrayData,
    total_len: usize,
    total_nulls: usize,
) error{OutOfMemory}!array_data.SharedBuffer {
    if (total_nulls == 0) return array_data.SharedBuffer.empty;
    const used = bitmap.byteLength(total_len);
    var owned = try buffer.OwnedBuffer.init(allocator, used);
    const bytes = owned.data[0..used];
    @memset(bytes, 0);
    var i: usize = 0;
    while (i < left.length) : (i += 1) {
        if (isValidAt(left, i)) bitmap.setBit(bytes, i);
    }
    i = 0;
    while (i < right.length) : (i += 1) {
        if (isValidAt(right, i)) bitmap.setBit(bytes, left.length + i);
    }
    return owned.toShared(used);
}

fn isValidAt(data: *const ArrayData, index: usize) bool {
    if (data.null_count) |count| {
        if (count == 0) return true;
        if (count == data.length) return false;
    }
    const validity = data.validity() orelse return true;
    return validity.isValid(data.offset + index) catch false;
}

fn bitAt(buf: array_data.SharedBuffer, bit_index: usize) bool {
    return bitmap.bitIsSet(buf.data, bit_index);
}

fn dataBytesForFixedWidth(data: *const ArrayData, byte_width: usize) ConcatArrayError![]const u8 {
    const start = std.math.mul(usize, data.offset, byte_width) catch return error.InvalidInput;
    const data_len = std.math.mul(usize, data.length, byte_width) catch return error.InvalidInput;
    const end = std.math.add(usize, start, data_len) catch return error.InvalidInput;
    if (data.buffers.len < 2) return error.InvalidInput;
    if (end > data.buffers[1].len()) return error.InvalidInput;
    return data.buffers[1].data[start..end];
}

fn requireBufferCount(data: *const ArrayData, min_count: usize) ConcatArrayError!void {
    if (data.buffers.len < min_count) return error.InvalidInput;
}

fn requireBitmapBits(buf: array_data.SharedBuffer, bit_len: usize) ConcatArrayError!void {
    if (bitmap.byteLength(bit_len) > buf.len()) return error.InvalidInput;
}

const std = @import("std");
const SharedBuffer = @import("buffer.zig").SharedBuffer;
const OwnedBuffer = @import("buffer.zig").OwnedBuffer;

// Return the number of bytes required to store the requested bit count.
//
// Cases:
// - byteLength(0) == 0
// - byteLength(1) == 1
// - byteLength(7) == 1
// - byteLength(8) == 1
// - byteLength(9) == 2
// - byteLength(63) == 8
// - byteLength(64) == 8
// - byteLength(65) == 9
pub fn byteLength(bit_length: usize) usize {
    return (bit_length + 7) >> 3;
}

fn bitMask(bit_index: usize) u8 {
    // Cases (LSB-first, index wraps every 8 bits):
    // - bitMask(0) == 0b0000_0001
    // - bitMask(1) == 0b0000_0010
    // - bitMask(7) == 0b1000_0000
    // - bitMask(8) == 0b0000_0001
    // - bitMask(9) == 0b0000_0010
    return @as(u8, 1) << @as(u3, @intCast(bit_index & 7));
}

// Read a single bit using Arrow's least-significant-bit-first order.
pub fn bitIsSet(data: []const u8, bit_index: usize) bool {
    // Cases:
    // - data = { 0b0000_0101 }, bitIsSet(data, 0) == true
    // - data = { 0b0000_0101 }, bitIsSet(data, 1) == false
    // - data = { 0b0000_0101 }, bitIsSet(data, 2) == true
    // - data = { 0b0000_0101, 0b0000_0010 }, bitIsSet(data, 9) == true
    // - data = { 0b0000_0101, 0b0000_0010 }, bitIsSet(data, 8) == false
    const byte = data[bit_index >> 3];
    return (byte & bitMask(bit_index)) != 0;
}

// Set a single bit in-place using Arrow's least-significant-bit-first bit order.
// Cases:
// - data = { 0b0000_0000 }, setBit(data, 0) => { 0b0000_0001 }
// - data = { 0b0000_0000 }, setBit(data, 7) => { 0b1000_0000 }
// - data = { 0b0000_0000, 0b0000_0000 }, setBit(data, 9) => { 0b0000_0000, 0b0000_0010 }
pub fn setBit(data: []u8, bit_index: usize) void {
    data[bit_index >> 3] |= bitMask(bit_index);
}

// Clear a single bit in-place using Arrow's least-significant-bit-first bit order.
// Cases:
// - data = { 0b1111_1111 }, clearBit(data, 0) => { 0b1111_1110 }
// - data = { 0b1111_1111 }, clearBit(data, 7) => { 0b0111_1111 }
// - data = { 0b1111_1111, 0b1111_1111 }, clearBit(data, 9) => { 0b1111_1111, 0b1111_1101 }
pub fn clearBit(data: []u8, bit_index: usize) void {
    data[bit_index >> 3] &= ~bitMask(bit_index);
}

// Write a single bit in-place with a boolean value.
// Cases:
// - data = { 0b0000_0000 }, writeBit(data, 1, true) => { 0b0000_0010 }
// - data = { 0b0000_0010 }, writeBit(data, 1, false) => { 0b0000_0000 }
// - data = { 0b0000_0000, 0b0000_0000 }, writeBit(data, 9, true) => { 0b0000_0000, 0b0000_0010 }
pub fn writeBit(data: []u8, bit_index: usize, value: bool) void {
    if (value) setBit(data, bit_index) else clearBit(data, bit_index);
}

// Number of bytes per SIMD lane group for the vectorised popcount path.
// 16 bytes == 128 bits (SSE2 / NEON tier).  Deliberately not 32 to work
// around a Zig 0.15.1 x86_64 codegen bug: the 32-lane path requires a
// VPMOVZXBD ymm,m128 encoding that the 0.15.1 backend cannot emit
// ("no encoding found for: none vpmovzxbd ymm m128 none none").
// With 16 lanes the maximum per-chunk lane sum is 16*8 = 128 ≤ u8::MAX,
// so no lane-widening before @reduce is needed, avoiding the problematic
// instruction entirely.  Performance is still 4-8× over the scalar loop.
const POPCOUNT_SIMD_LANES = 16;

// Count set bits across the logical length, ignoring padding bits.
//
// Uses a @Vector SIMD loop for the bulk of the work so that the compiler can
// emit vectorised popcount instructions (VPOPCNTB / NEON VCNT).  A scalar
// tail handles the remaining bytes and the final partial byte.
pub fn countSetBit(data: []const u8, bit_len: usize) usize {
    if (bit_len == 0) return 0;

    const full_bytes = bit_len >> 3;
    const remainder = bit_len & 7;

    var count: usize = 0;
    var offset: usize = 0;

    // SIMD bulk: POPCOUNT_SIMD_LANES bytes per iteration.
    // @popCount on a @Vector yields per-lane bit counts (each 0..8).
    // With 16 lanes the maximum aggregate is 16*8 = 128 ≤ u8::MAX,
    // so @reduce returns u8 without wrapping — no lane-widening needed.
    const simd_end = (full_bytes / POPCOUNT_SIMD_LANES) * POPCOUNT_SIMD_LANES;
    while (offset < simd_end) : (offset += POPCOUNT_SIMD_LANES) {
        const vec: @Vector(POPCOUNT_SIMD_LANES, u8) = data[offset..][0..POPCOUNT_SIMD_LANES].*;
        const lane_counts: @Vector(POPCOUNT_SIMD_LANES, u8) = @popCount(vec);
        count += @reduce(.Add, lane_counts);
    }

    // Scalar tail for remaining full bytes.
    while (offset < full_bytes) : (offset += 1) {
        count += @popCount(data[offset]);
    }

    // Partial final byte: mask off padding bits before counting.
    if (remainder > 0) {
        const last_byte = data[full_bytes];
        const mask = (@as(u8, 1) << @as(u3, @intCast(remainder))) - 1;
        count += @popCount(last_byte & mask);
    }

    return count;
}

// Count unset bits across the logical length, ignoring padding bits.
pub fn countUnsetBit(data: []const u8, bit_len: usize) usize {
    return bit_len - countSetBit(data, bit_len);
}

// Count set bits in the half-open range [start_bit, end_bit).
// Correctly handles non-zero start offsets, avoiding O(n) element-by-element scanning.
pub fn countSetBitsInRange(data: []const u8, start_bit: usize, end_bit: usize) usize {
    if (start_bit >= end_bit) return 0;
    // Fast path: zero-based range delegates to the existing full-scan helper.
    if (start_bit == 0) return countSetBit(data, end_bit);

    const first_byte = start_bit >> 3;
    const last_byte = (end_bit - 1) >> 3;

    var count: usize = 0;

    if (first_byte == last_byte) {
        // All bits are within a single byte.
        const lo_bit = @as(u3, @intCast(start_bit & 7));
        const hi_bit = @as(u3, @intCast((end_bit - 1) & 7));
        const hi_shift = @as(u4, hi_bit) + 1; // range 1..8
        const hi_mask: u8 = if (hi_shift >= 8) 0xFF else (@as(u8, 1) << @as(u3, @intCast(hi_shift))) - 1;
        const lo_mask: u8 = ~((@as(u8, 1) << lo_bit) - 1);
        return @popCount(data[first_byte] & lo_mask & hi_mask);
    }

    // First byte: bits from (start_bit & 7) through the high end of the byte.
    const lo_bit = @as(u3, @intCast(start_bit & 7));
    const first_mask: u8 = ~((@as(u8, 1) << lo_bit) - 1);
    count += @popCount(data[first_byte] & first_mask);

    // Full middle bytes: delegate to countSetBit so the SIMD loop is reused
    // automatically when the middle region is large enough.
    const mid = data[first_byte + 1 .. last_byte];
    if (mid.len > 0) count += countSetBit(mid, mid.len * 8);

    // Last byte: bits from 0 through (end_bit-1) & 7.
    const hi_bit = @as(u3, @intCast((end_bit - 1) & 7));
    const hi_shift = @as(u4, hi_bit) + 1;
    const last_mask: u8 = if (hi_shift >= 8) 0xFF else (@as(u8, 1) << @as(u3, @intCast(hi_shift))) - 1;
    count += @popCount(data[last_byte] & last_mask);

    return count;
}

// Count unset bits in the half-open range [start_bit, end_bit).
pub fn countUnsetBitsInRange(data: []const u8, start_bit: usize, end_bit: usize) usize {
    if (start_bit >= end_bit) return 0;
    return (end_bit - start_bit) - countSetBitsInRange(data, start_bit, end_bit);
}

fn clearTrailingBits(bytes: []u8, len: usize, valid: bool) void {
    if (len == 0 or bytes.len == 0) return;

    const remainder = len & 7;
    if (remainder == 0) return;

    const last = bytes.len - 1;
    const keep_mask = (@as(u8, 1) << @as(u3, @intCast(remainder))) - 1;
    bytes[last] &= keep_mask;
    if (valid) bytes[last] |= keep_mask;
}

