        var msg = fbs.MessageT{
            .version = toFbsMetadataVersion(self.metadata_version),
            .header = .{ .Schema = schema_ptr },
            .bodyLength = 0,
            .custom_metadata = try std.ArrayList(fbs.KeyValueT).initCapacity(self.allocator, 0),
