const std = @import("std");
const zarrow = @import("zarrow");

var g_io: std.Io = undefined;
var g_filter: []const u8 = "";

fn now() std.Io.Timestamp {
    return std.Io.Timestamp.now(g_io, .awake);
}
fn since(t: std.Io.Timestamp) u64 {
    return @intCast(t.untilNow(g_io, .awake).toNanoseconds());
}
fn report(name: []const u8, ns: u64, units: usize, unit: []const u8) void {
    const per = @as(f64, @floatFromInt(ns)) / @as(f64, @floatFromInt(units));
    std.debug.print("probe={s} total_ms={d:.2} ns_per_{s}={d:.3}\n", .{ name, @as(f64, @floatFromInt(ns)) / 1e6, unit, per });
}
fn want(name: []const u8) bool {
    return g_filter.len == 0 or std.mem.indexOf(u8, name, g_filter) != null;
}

const names = [_][]const u8{ "alpha", "beta", "gamma", "delta-long-name" };
const int32_type = zarrow.DataType{ .int32 = {} };
const int64_type = zarrow.DataType{ .int64 = {} };
const bool_type = zarrow.DataType{ .bool = {} };
const string_type = zarrow.DataType{ .string = {} };
const item_field = zarrow.Field{ .name = "item", .data_type = &int32_type, .nullable = true };
const list_type = zarrow.DataType{ .list = .{ .value_field = item_field } };

fn buildInt32(a: std.mem.Allocator, n: usize, null_every: usize) !zarrow.ArrayRef {
    var b = try zarrow.Int32Builder.init(a, n);
    defer b.deinit();
    for (0..n) |i| {
        if (null_every != 0 and i % null_every == 0) try b.appendNull() else try b.append(@intCast(i));
    }
    return b.finish();
}
fn buildString(a: std.mem.Allocator, n: usize, null_every: usize) !zarrow.ArrayRef {
    var b = try zarrow.StringBuilder.init(a, n, n * 8);
    defer b.deinit();
    for (0..n) |i| {
        if (null_every != 0 and i % null_every == 0) try b.appendNull() else try b.append(names[i & 3]);
    }
    return b.finish();
}
fn buildBool(a: std.mem.Allocator, n: usize, period: usize) !zarrow.ArrayRef {
    var b = try zarrow.BooleanBuilder.init(a, n);
    defer b.deinit();
    for (0..n) |i| try b.append(i % period == 0);
    return b.finish();
}
fn buildList(a: std.mem.Allocator, n: usize, null_every: usize) !zarrow.ArrayRef {
    var lb = try zarrow.ListBuilder.init(a, 0, item_field);
    defer lb.deinit();
    var vb = try zarrow.Int32Builder.init(a, 0);
    defer vb.deinit();
    for (0..n) |i| {
        if (null_every != 0 and i % null_every == 0) {
            try lb.appendNull();
        } else {
            try vb.append(@intCast(i));
            try vb.append(@intCast(i + 1));
            try vb.append(@intCast(i + 2));
            try lb.appendLen(3);
        }
    }
    var values = try vb.finish();
    defer values.release();
    return lb.finish(values);
}

fn probeBuilders(a: std.mem.Allocator) !void {
    const n: usize = 1_000_000;
    const iters: usize = 5;
    if (want("string_builder")) {
        inline for (.{ 0, 7 }) |null_every| {
            inline for (.{ false, true }) |presize| {
                var t: u64 = 0;
                for (0..iters) |_| {
                    const s = now();
                    var b = if (presize) try zarrow.StringBuilder.init(a, n, n * 8) else try zarrow.StringBuilder.init(a, 0, 0);
                    defer b.deinit();
                    for (0..n) |i| {
                        if (null_every != 0 and i % null_every == 0) try b.appendNull() else try b.append(names[i & 3]);
                    }
                    var r = try b.finish();
                    r.release();
                    t += since(s);
                }
                const nm = "string_builder" ++ (if (presize) "_presized" else "_grow") ++ (if (null_every == 0) "" else "_nulls");
                report(nm, t, n * iters, "row");
            }
        }
    }
    if (want("bool_builder")) {
        inline for (.{ 0, 7 }) |null_every| {
            var t: u64 = 0;
            for (0..iters) |_| {
                const s = now();
                var b = try zarrow.BooleanBuilder.init(a, 0);
                defer b.deinit();
                for (0..n) |i| {
                    if (null_every != 0 and i % null_every == 0) try b.appendNull() else try b.append((i & 1) == 0);
                }
                var r = try b.finish();
                r.release();
                t += since(s);
            }
            report(if (null_every == 0) "bool_builder" else "bool_builder_nulls", t, n * iters, "row");
        }
    }
    if (want("list_builder")) {
        var t: u64 = 0;
        for (0..iters) |_| {
            const s = now();
            var r = try buildList(a, n, 7);
            r.release();
            t += since(s);
        }
        report("list_builder_nulls_3vals", t, n * iters, "row");
    }
    if (want("struct_builder")) {
        const fields = [_]zarrow.Field{
            .{ .name = "id", .data_type = &int32_type, .nullable = true },
            .{ .name = "ok", .data_type = &bool_type, .nullable = true },
        };
        var t: u64 = 0;
        for (0..iters) |_| {
            const s = now();
            var sb = zarrow.StructBuilder.init(a, fields[0..]);
            defer sb.deinit();
            var ib = try zarrow.Int32Builder.init(a, 0);
            defer ib.deinit();
            var bb = try zarrow.BooleanBuilder.init(a, 0);
            defer bb.deinit();
            for (0..n) |i| {
                if (i % 7 == 0) {
                    try sb.appendNull();
                    try ib.appendNull();
                    try bb.appendNull();
                } else {
                    try sb.appendValid();
                    try ib.append(@intCast(i));
                    try bb.append((i & 1) == 0);
                }
            }
            var ir = try ib.finish();
            defer ir.release();
            var br = try bb.finish();
            defer br.release();
            var r = try sb.finish(&[_]zarrow.ArrayRef{ ir, br });
            r.release();
            t += since(s);
        }
        report("struct_builder_nulls", t, n * iters, "row");
    }
}

fn probeConcat(a: std.mem.Allocator) !void {
    if (!want("concat")) return;
    const n: usize = 1_000_000;
    var ints = try buildInt32(a, n, 7);
    defer ints.release();
    var strs = try buildString(a, n, 7);
    defer strs.release();
    var bools = try buildBool(a, n, 3);
    defer bools.release();
    inline for (.{ "int32", "string", "bool" }) |kind| {
        const src = if (comptime std.mem.eql(u8, kind, "int32")) ints else if (comptime std.mem.eql(u8, kind, "string")) strs else bools;
        const dt = if (comptime std.mem.eql(u8, kind, "int32")) int32_type else if (comptime std.mem.eql(u8, kind, "string")) string_type else bool_type;
        for ([_]usize{ 2, 100, 10_000, 100_000 }) |k| {
            const part = n / k;
            const parts = try a.alloc(zarrow.ArrayRef, k);
            defer a.free(parts);
            for (parts, 0..) |*p, i| p.* = try src.slice(i * part, part);
            defer for (parts) |*p| p.release();
            const s = now();
            var out = try zarrow.concatArrayRefs(a, dt, parts);
            const t = since(s);
            out.release();
            var buf: [64]u8 = undefined;
            const nm = try std.fmt.bufPrint(&buf, "concat_{s}_k{d}", .{ kind, k });
            report(nm, t, n, "row");
        }
    }
}

fn probeFilterTake(a: std.mem.Allocator) !void {
    const C = zarrow.compute;
    inline for (.{ "int32", "string", "list" }) |kind| {
        if (want("filter") or want("take")) {
            const n: usize = if (comptime std.mem.eql(u8, kind, "int32")) 1_000_000 else 100_000;
            var src = if (comptime std.mem.eql(u8, kind, "int32")) try buildInt32(a, n, 7) else if (comptime std.mem.eql(u8, kind, "string")) try buildString(a, n, 7) else try buildList(a, n, 7);
            defer src.release();
            var pred = try buildBool(a, n, 2);
            defer pred.release();
            if (want("filter")) {
                const s = now();
                var out = try C.datumFilter(C.Datum.fromArray(src), C.Datum.fromArray(pred), .{});
                const t = since(s);
                out.release();
                report("filter_" ++ kind ++ "_50pct", t, n, "row");
                const s2 = now();
                const sel = try C.datumFilterSelectionIndices(a, C.Datum.fromArray(pred), n, .{});
                const t2 = since(s2);
                a.free(sel);
                report("filter_selection_indices_" ++ kind, t2, n, "row");
            }
            if (want("take")) {
                const idx = try a.alloc(usize, n);
                defer a.free(idx);
                for (idx, 0..) |*x, i| x.* = (i * 7919 + 13) % n;
                const s = now();
                var out = try C.datumTake(C.Datum.fromArray(src), idx);
                const t = since(s);
                out.release();
                report("take_" ++ kind, t, n, "row");
            }
        }
    }
}

fn writeStream(a: std.mem.Allocator, sink: *std.Io.Writer.Allocating, schema: zarrow.Schema, batch: zarrow.RecordBatch, nb: usize, codec: ?zarrow.IpcBodyCompressionCodec) !u64 {
    const s = now();
    var w = if (codec) |c| zarrow.IpcStreamWriter.initWithBodyCompression(a, &sink.writer, c) else zarrow.IpcStreamWriter.init(a, &sink.writer);
    defer w.deinit();
    try w.writeSchema(schema);
    for (0..nb) |_| try w.writeRecordBatch(batch);
    try w.writeEnd();
    return since(s);
}
fn readStream(a: std.mem.Allocator, bytes: []const u8, zero_copy: bool) !u64 {
    var owned = try zarrow.OwnedBuffer.initUninit(a, bytes.len);
    @memcpy(owned.data[0..bytes.len], bytes);
    var source = try owned.toShared(bytes.len);
    defer source.release();
    const s = now();
    var fixed: std.Io.Reader = .fixed(source.data);
    var r = if (zero_copy) zarrow.IpcStreamReader.initZeroCopy(a, &fixed, source) else zarrow.IpcStreamReader.init(a, &fixed);
    defer r.deinit();
