# Offsets: scan only the window [start, total_len] (slices of big arrays validate in O(length)).
for T in ('i32', 'i64'):
    rep(f'''    fn validateOffsets{T.upper()}(offsets: []const {T}, total_len: usize, data_len: usize) ValidationError!void {{
        const needed_len = std.math.add(usize, total_len, 1) catch return error.InvalidOffsets;
        if (offsets.len < needed_len) return error.BufferTooSmall;
        var prev: {T} = offsets[0];
        if (prev < 0) return error.InvalidOffsets;
        var i: usize = 1;''',
f'''    fn validateOffsets{T.upper()}(offsets: []const {T}, start: usize, total_len: usize, data_len: usize) ValidationError!void {{
        const needed_len = std.math.add(usize, total_len, 1) catch return error.InvalidOffsets;
        if (offsets.len < needed_len) return error.BufferTooSmall;
        var prev: {T} = offsets[start];
        if (prev < 0) return error.InvalidOffsets;
        var i: usize = start + 1;''')
    rep(f'''    fn validateOffsetsSizes{T.upper()}(offsets: []const {T}, sizes: []const {T}, total_len: usize, child_len: usize) ValidationError!void {{
        if (offsets.len < total_len) return error.BufferTooSmall;
        if (sizes.len < total_len) return error.BufferTooSmall;
        var i: usize = 0;''',
f'''    fn validateOffsetsSizes{T.upper()}(offsets: []const {T}, sizes: []const {T}, start: usize, total_len: usize, child_len: usize) ValidationError!void {{
        if (offsets.len < total_len) return error.BufferTooSmall;
