    // Nullable int32 + string columns cut into 16-row parts (unaligned bit offsets), as filter/take/chunk flattening produce.
    var ints, var strs = try buildSources(allocator, cfg.rows);
    defer ints.release();
    defer strs.release();
    const part_rows: usize = 16;
