        for (0..reps) |_| acc += ZSTD_compress(&out, out.len, &input, input.len, 1);
        report("p3_ZSTD_compress_400B", since(s), reps, "call");
        const cctx = ZSTD_createCCtx();
        defer _ = ZSTD_freeCCtx(cctx);
        var clen: usize = 0;
