```zig
fn takeStructArray(allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: []const ?usize) KernelError!?ArrayRef {
    if (src.data_type != .struct_ or src.buffers.len < 1) return null;
    for (indices) |m| if (m) |idx| if (idx >= src.length) return error.InvalidInput;
    const src_validity = src.validity();
    const out_len = indices.len;
    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
    errdefer validity.deinit();
    var null_count: usize = 0;
    for (indices, 0..) |m, i| {
        const idx = m orelse { null_count += 1; continue; };
        if (!validAt(src_validity, src.offset + idx)) { null_count += 1; continue; }
        bitmap.setBit(validity.data, i);
    }
    const child_indices = allocator.alloc(?usize, out_len) catch return error.OutOfMemory;
    defer allocator.free(child_indices);
    const children = allocator.alloc(ArrayRef, src.children.len) catch return error.OutOfMemory;
    var filled: usize = 0;
    errdefer { for (children[0..filled]) |*c| c.release(); allocator.free(children); }
    for (src.children) |child| {
        const clen = child.data().length;
        const base: usize = if (clen >= src.offset + src.length) src.offset else if (clen >= src.length) 0 else return error.InvalidInput;
        for (indices, child_indices) |m, *ci| ci.* = if (m) |idx| base + idx else null;
        var taken = try datumTakeArrayLikeNullable(allocator, Datum.fromArray(child), child.data().data_type, child_indices);
        if (taken != .array) { taken.release(); return error.InvalidInput; }
        children[filled] = taken.array;
        filled += 1;
    }
    var buffers: [1]buffer.SharedBuffer = undefined;
    buffers[0] = if (null_count == 0) blk: { validity.deinit(); break :blk buffer.SharedBuffer.empty; }
        else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
    errdefer buffers[0].release();
    return ArrayRef.fromOwnedInlineBuffers(allocator, .{ .data_type = src.data_type, .length = out_len,
        .null_count = null_count, .buffers = buffers[0..], .children = children }) catch return error.OutOfMemory;
}
```
