### P2-A struct take kernel (`src/compute/datum_permutation.zig`), 3092 ns/row -> target under 30
Child row mapping must mirror `sliceStructChildRef` in concat_array_refs.zig. If
`child.length >= parent.offset + parent.length`, the child row is `parent.offset + idx`; else if
`child.length >= parent.length`, it is `idx`; else the input is invalid.
```zig
fn takeStructArray(allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: []const ?usize) KernelError!?ArrayRef {
    if (src.data_type != .struct_ or src.buffers.len < 1) return null;
    for (indices) |m| if (m) |idx| if (idx >= src.length) return error.InvalidInput;
    const src_validity = src.validity();
    const out_len = indices.len;
    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
    errdefer validity.deinit();
    var null_count: usize = 0;
    for (indices, 0..) |m, i| {
        const idx = m orelse { null_count += 1; continue; };
        if (!validAt(src_validity, src.offset + idx)) { null_count += 1; continue; }
        bitmap.setBit(validity.data, i);
    }
    const child_indices = allocator.alloc(?usize, out_len) catch return error.OutOfMemory;
    defer allocator.free(child_indices);
    const children = allocator.alloc(ArrayRef, src.children.len) catch return error.OutOfMemory;
    var filled: usize = 0;
    errdefer { for (children[0..filled]) |*c| c.release(); allocator.free(children); }
    for (src.children) |child| {
        const clen = child.data().length;
        const base: usize = if (clen >= src.offset + src.length) src.offset else if (clen >= src.length) 0 else return error.InvalidInput;
        for (indices, child_indices) |m, *ci| ci.* = if (m) |idx| base + idx else null;
        var taken = try datumTakeArrayLikeNullable(allocator, Datum.fromArray(child), child.data().data_type, child_indices);
        if (taken != .array) { taken.release(); return error.InvalidInput; }
        children[filled] = taken.array;
        filled += 1;
    }
    var buffers: [1]buffer.SharedBuffer = undefined;
    buffers[0] = if (null_count == 0) blk: { validity.deinit(); break :blk buffer.SharedBuffer.empty; }
        else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
    errdefer buffers[0].release();
    return ArrayRef.fromOwnedInlineBuffers(allocator, .{ .data_type = src.data_type, .length = out_len,
        .null_count = null_count, .buffers = buffers[0..], .children = children }) catch return error.OutOfMemory;
}
```
Dispatch: add `.struct_ => try takeStructArray(allocator, src, indices),` to the switch from T3.
Test (test_datum.zig): struct{int32, string} built with StructBuilder, parent nulls at rows 1 and 4, `slice(1, n-1)`.
Take indices `{3, null, 0, 2, 2}`. Check parent `isNull` per row and, for valid rows, `StructArray.field(k)` values.
Repeat on an unsliced parent whose children were sliced first (the second mapping branch).
Done when: probe `p2_take_struct2` is under 30 ns/row; struct filter tests still pass.

### P2-B chunked datum filter/take via per-chunk gather (same file), 133 / 52 ns/row -> target under 10
New helper. `selections` come from `datumFilterSelectionIndices`, so non-null entries are non-decreasing:
```zig
/// Splits sorted logical selections by chunk and gathers each chunk once (fast kernels).
fn takeChunkedSorted(allocator: std.mem.Allocator, chunks: ChunkedArray, out_type: DataType, selections: []const ?usize) KernelError![]ArrayRef {
    var out: std.ArrayList(ArrayRef) = .empty;
    errdefer { for (out.items) |*c| c.release(); out.deinit(allocator); }
    var local: std.ArrayList(?usize) = .empty;
    defer local.deinit(allocator);
    var chunk_idx: usize = 0;
    var chunk_start: usize = 0;
    for (selections) |sel| {
        if (sel) |logical| {
            if (logical < chunk_start) return error.InvalidInput; // not sorted
            while (chunk_idx < chunks.numChunks() and logical >= chunk_start + chunks.chunk(chunk_idx).data().length) {
                try flushChunkTake(allocator, &out, &local, chunks, chunk_idx, out_type);
                chunk_start += chunks.chunk(chunk_idx).data().length;
                chunk_idx += 1;
            }
            if (chunk_idx >= chunks.numChunks()) return error.InvalidInput;
            try local.append(allocator, logical - chunk_start);
        } else try local.append(allocator, null);
    }
    try flushChunkTake(allocator, &out, &local, chunks, chunk_idx, out_type);
    return out.toOwnedSlice(allocator);
}

fn flushChunkTake(allocator: std.mem.Allocator, out: *std.ArrayList(ArrayRef), local: *std.ArrayList(?usize), chunks: ChunkedArray, chunk_idx: usize, out_type: DataType) KernelError!void {
    if (local.items.len == 0) return;
    const piece = if (chunk_idx < chunks.numChunks()) blk: {
        var taken = try datumTakeArrayLikeNullable(allocator, Datum.fromArray(chunks.chunk(chunk_idx).*), out_type, local.items);
        if (taken != .array) { taken.release(); return error.InvalidInput; }
        break :blk taken.array;
    } else try builders.buildNullLikeArray(allocator, out_type, local.items.len); // only nulls past the end
    try appendOwnedArrayRef(allocator, out, piece);
    local.clearRetainingCapacity();
}
```
Use it in two places:
- `datumFilter`: before the `pieces` loop add `if (datum == .chunked) { selections = datumFilterSelectionIndices(...);
  parts = takeChunkedSorted(...); defer release+free; if parts.len == 0 return empty-like;
  return Datum.fromArray(concatArrayRefs(allocator, out_type, parts) catch |err| return common.mapConcatError(err)); }`.
- `datumFilterChunkAware`: when `datum == .chunked`, build `ChunkedArray.init(allocator, out_type, parts)` (init retains;
  release `parts` afterwards exactly like `datumTakeChunkedNullable` does) and return `Datum.fromChunked`.
Leave `datumTake`/`datumTakeNullable` on chunked alone: their indices are not sorted.
Tests: existing "datumFilterSelectionIndices and datumFilterChunkAware stay consistent..." and "datumFilter keeps
compatibility array output shape for chunked inputs" must pass. Add one with string chunks of lengths {3, 0, 5}
and a predicate with nulls (drop_nulls false), and compare against filtering the concatenated array.
Done when: probes `p2_filter_chunked_string_50pct` and `p2_filterChunkAware...` are under 10 ns/row.

### P2-C N-ary list/large_list/struct concat (`src/concat_array_refs.zig`), 250 ns/row at 20k parts -> under 10
Add `concatManyNested(allocator, dt, parts) Error!?ArrayRef`, called in `concatArrayRefs` right after
`concatManyFlat`. It handles `.list`/`.map` (i32 offsets), `.large_list` (i64) and `.struct_`, and returns null otherwise.
